"""Tests for bin/hq_floor_mcp.py (the Claude Desktop to herdr floor bridge).

Drives the real server as a subprocess over stdio with a FAKE `herdr` on PATH,
so every assertion is against bytes the server actually emitted. The fake
records its argv so the allowlist can be checked by what reached the binary,
not by what the server claims.
"""

from __future__ import annotations

import json
import os
import stat
import subprocess
import sys
from pathlib import Path

import pytest

SERVER = Path(__file__).resolve().parents[1] / "bin" / "hq_floor_mcp.py"

FAKE_HERDR = r"""#!/bin/bash
printf '%s\n' "$*" >> "$HQ_FAKE_LOG"
case "$1 $2" in
  "workspace list") echo '{"id":"x","result":{"type":"workspace_list","workspaces":[{"workspace_id":"wQB","label":"demo floor","agent_status":"working"}]}}' ;;
  "agent list") echo '{"id":"x","result":{"agents":[{"name":"conductor-one","agent_status":"working","pane_id":"wQB:p1","tokens":{"repo":"demo","wt":"main"}}]}}' ;;
  "agent read") echo '{"id":"x","result":{"text":"RECAP: all quiet"}}' ;;
  "agent prompt") echo '{"id":"x","result":{"submitted":true,"target":"'"$3"'"}}' ;;
  "notification show") echo '{"id":"x","result":{"shown":true}}' ;;
  *) echo '{"id":"x","error":{"code":"unknown","message":"fake herdr: unknown"}}' >&2; exit 1 ;;
esac
"""


@pytest.fixture
def bridge(tmp_path: Path):
    """Return a callable that runs the server once over stdio.

    The callable takes an optional `env` mapping of extra environment
    variables, so a test can exercise a different HQ_FLOOR_PROMPT_ALLOW
    without a second fixture.
    """
    fake = tmp_path / "herdr"
    fake.write_text(FAKE_HERDR, encoding="utf-8")
    fake.chmod(fake.stat().st_mode | stat.S_IXUSR)
    log = tmp_path / "argv.log"
    floor = tmp_path / "floor"
    base_env = {
        **os.environ,
        "HQ_FLOOR_HERDR": str(fake),
        "HQ_FLOOR_DIR": str(floor),
        "HQ_FAKE_LOG": str(log),
    }
    base_env.pop("HQ_FLOOR_PROMPT_ALLOW", None)

    def call(messages: list[dict], env: dict | None = None) -> list[dict]:
        stdin = "".join(json.dumps(m) + "\n" for m in messages)
        proc = subprocess.run(
            [sys.executable, str(SERVER)],
            input=stdin,
            capture_output=True,
            text=True,
            env={**base_env, **(env or {})},
            timeout=30,
        )
        assert proc.returncode == 0, proc.stderr
        return [json.loads(line) for line in proc.stdout.splitlines() if line.strip()]

    call.log = log  # type: ignore[attr-defined]
    call.floor = floor  # type: ignore[attr-defined]
    return call


def _rpc(mid, method, params=None):
    msg = {"jsonrpc": "2.0", "id": mid, "method": method}
    if params is not None:
        msg["params"] = params
    return msg


def _tool(mid, name, **arguments):
    return _rpc(mid, "tools/call", {"name": name, "arguments": arguments})


def test_initialize_and_tools_list(bridge):
    out = bridge(
        [
            _rpc(1, "initialize", {}),
            {"jsonrpc": "2.0", "method": "notifications/initialized"},
            _rpc(2, "tools/list"),
        ]
    )
    assert out[0]["result"]["serverInfo"]["name"] == "hq-floor"
    assert out[0]["result"]["capabilities"] == {"tools": {}}
    names = {t["name"] for t in out[1]["result"]["tools"]}
    assert names == {
        "floor_status",
        "floor_read",
        "floor_prompt",
        "floor_inbox",
        "floor_notify",
    }
    # the full CLI proxy that was considered and rejected must not exist, by name
    assert not any(
        n.startswith(("floor_station", "floor_close", "floor_names")) for n in names
    )


def test_status_condenses_both_lists(bridge):
    out = bridge([_tool(1, "floor_status")])
    text = out[0]["result"]["content"][0]["text"]
    assert out[0]["result"]["isError"] is False
    assert text.startswith("workspaces 1 · agents 1")
    assert "conductor-one · working · demo · main · pane wQB:p1" in text
    assert bridge.log.read_text().splitlines() == ["workspace list", "agent list"]


def test_prompt_allowlist_refuses_a_lane_before_touching_herdr(bridge):
    out = bridge([_tool(1, "floor_prompt", target="promote-0908b", text="ship it")])
    res = out[0]["result"]
    assert res["isError"] is True
    assert "refused" in res["content"][0]["text"]
    assert not bridge.log.exists(), "a refused target must never reach the herdr binary"


@pytest.mark.parametrize("target", ["comms-desk", "conductor-one", "conductor"])
def test_prompt_default_allowlist_accepts_desks_and_conductors(bridge, target):
    out = bridge([_tool(1, "floor_prompt", target=target, text="read the inbox")])
    assert out[0]["result"]["isError"] is False
    assert bridge.log.read_text().strip() == f"agent prompt {target} read the inbox"


def test_prompt_allow_env_can_widen_to_a_custom_lane_name(bridge):
    """A floor that does not use the default role names configures instead of patching."""
    call = _tool(1, "floor_prompt", target="frontdoor", text="read the inbox")
    refused = bridge([call])
    assert refused[0]["result"]["isError"] is True
    assert "HQ_FLOOR_PROMPT_ALLOW" in refused[0]["result"]["content"][0]["text"]

    bridge.log.unlink(missing_ok=True)
    allowed = bridge([call], env={"HQ_FLOOR_PROMPT_ALLOW": "frontdoor,*-desk"})
    assert allowed[0]["result"]["isError"] is False
    assert bridge.log.read_text().strip() == "agent prompt frontdoor read the inbox"


def test_prompt_allow_env_can_narrow_below_the_default(bridge):
    """Narrowing is the point: a desk row the default admits can be locked out."""
    out = bridge(
        [_tool(1, "floor_prompt", target="comms-desk", text="hello")],
        env={"HQ_FLOOR_PROMPT_ALLOW": "conductor"},
    )
    assert out[0]["result"]["isError"] is True
    assert not bridge.log.exists()


@pytest.mark.parametrize("target", ["-h", "Conductor", "a b", "x;whoami", "../etc"])
def test_structural_name_gate_holds_even_when_allowlist_is_wide_open(bridge, target):
    """HQ_FLOOR_PROMPT_ALLOW can narrow, never widen: NAME_RE is not configurable."""
    out = bridge(
        [_tool(1, "floor_prompt", target=target, text="hello")],
        env={"HQ_FLOOR_PROMPT_ALLOW": "*"},
    )
    assert out[0]["result"]["isError"] is True
    assert "structurally valid" in out[0]["result"]["content"][0]["text"]
    assert not bridge.log.exists(), (
        "a malformed target must never reach the herdr binary"
    )


