def test_inbox_writes_one_corridor_file(bridge):
    out = bridge(
        [
            _tool(
                1,
                "floor_inbox",
                hat="sales",
                title="Acme Corp: confirm Thursday",
                body="Draft ready at notes/acme-corp/2026-01-02-confirm-demo.md",
            )
        ]
    )
    res = out[0]["result"]
    assert res["isError"] is False
    path = Path(res["content"][0]["text"])
    assert path.parent == bridge.floor / "inbox"
    assert path.name.endswith("-sales-acme-corp-confirm-thursday.md")
    body = path.read_text(encoding="utf-8")
    assert body.startswith(
        "# Acme Corp: confirm Thursday\n\nfrom: sales-desk (Claude Desktop)"
    )
    assert not bridge.log.exists(), "inbox is a file write, it must not call herdr"


def test_read_and_notify_reach_herdr_with_the_expected_argv(bridge):
    out = bridge(
        [
            _tool(1, "floor_read", agent="conductor-one", lines=40),
            _tool(2, "floor_notify", title="NEEDS YOU", body="the mail arrived"),
        ]
    )
    assert out[0]["result"]["content"][0]["text"] == "RECAP: all quiet"
    assert out[1]["result"]["content"][0]["text"] == "shown"
    assert bridge.log.read_text().splitlines() == [
        "agent read conductor-one --source recent-unwrapped --lines 40",
        "notification show NEEDS YOU --body=the mail arrived",
    ]


